func TestPreviewLongNonASCII(t *testing.T) {
	text := strings.Repeat("é", 100)
	want := strings.Repeat("é", previewLen) + "…"
	if got := Preview(text); got != want {
		t.Errorf("Preview(100 é) = %q, want %q", got, want)
	}
}
